contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 shareAmount) public payable {
        uint256 beforeTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeSellerBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sellShares(shareAmount, address(this), 0, 0, "", block.timestamp + 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterSellerBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        assert(afterTotalSupply <= beforeTotalSupply && afterSellerBalance <= beforeSellerBalance);
    }
}

