import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(uint256 shareAmount) internal {
        uint256 beforeTotalSupply;
        try c.totalSupply() returns (uint256 __r) { beforeTotalSupply = __r; } catch { return; }
        uint256 beforeSellerBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeSellerBalance = __r; } catch { return; }
        bool reverted;
        try c.sellShares(shareAmount, address(this), 0, 0, "", block.timestamp + 1) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTotalSupply;
        try c.totalSupply() returns (uint256 __r) { afterTotalSupply = __r; } catch { return; }
        uint256 afterSellerBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { afterSellerBalance = __r; } catch { return; }
        assertTrue(afterTotalSupply <= beforeTotalSupply && afterSellerBalance <= beforeSellerBalance);
    }

    function testFuzz_run(uint256 shareAmount) public {
        _run(shareAmount);
    }

    receive() external payable {}
}
